tmp_path = PosixPath('/tmp/pytest-of-root/pytest-131/test_declared_symlink_drift_de0') source = 'artifact', dangling = False
@pytest.mark.parametrize("source", ["artifact", "evidence"]) @pytest.mark.parametrize("dangling", [False, True]) def test_declared_symlink_drift_denies_atomically(tmp_path, source, dangling): host, owner, request, store, receipt = fixture(tmp_path) path = receipt.candidate.artifact if source == "artifact" else receipt.gate.evidence[0].path expected = (receipt.candidate.artifact_sha256 if source == "artifact" else receipt.gate.evidence[0].sha256) scoped = reopen_request(host, owner, request) replace_with_link(path, tmp_path, dangling) with pytest.raises(PermissionError, match="LANE_ARTIFACT_SCOPE"): digest_file(path, tmp_path) drift, drift_denial = None, None try: drift = source_changed(path, expected, tmp_path) except PermissionError as error: drift_denial = str(error) before = state(host) reopened, reopen_denial = None, None try: reopened = store.reopen(owner, scoped, event(), lambda: Clock(now=12.0)) except PermissionError as error: reopen_denial = str(error) witness = {"source": source, "dangling": dangling, "drift": drift, "drift_denial": drift_denial, "reopen_denial": reopen_denial, "invalidated": None if reopened is None else list(reopened.invalidated_candidates), "before": before, "after": state(host)} (tmp_path / "drift_symlink_observed.json").write_text(json.dumps(witness)) print(json.dumps(witness)) > assert drift_denial == reopen_denial == "LANE_ARTIFACT_SCOPE" E AssertionError: assert None == 'LANE_ARTIFACT_SCOPE'
